  static func ==(lhs: Aii_V1_Verified, rhs: Aii_V1_Verified) -> Bool {
    if lhs.record != rhs.record {return false}
    if lhs.seal != rhs.seal {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
